// Student helper: Group matches by user_id and format readable email body
// IMPORTANT SAFETY: Only send to test email addresses, never spam real users
const rawItems = $input.all();
const userMap = {};

for (const item of rawItems) {
  const row = item.json;
  const uid = row.user_id;
  if (!userMap[uid]) {
    userMap[uid] = {
      user_id: uid,
      original_email: row.email,
      loans: []
    };
  }
  userMap[uid].loans.push({
    bank: row.bank_name,
    product: row.product_name,
    rate: row.interest_rate
  });
}

const output = [];
for (const uid in userMap) {
  const u = userMap[uid];
  const loanSummaries = u.loans.map(l => `${l.bank} (${l.product}) @ ${l.rate}%`).join(' and ');

  // Safety test address routing: only route to verified test inbox
  let safeRecipient = 'student+test1@gmail.com';
  if (u.original_email.includes('+test')) {
    safeRecipient = u.original_email;
  }

  const emailBody = `Hi User ${u.user_id},\n\nCongratulations! You are eligible for:\n${loanSummaries}\n\nBest regards,\nSmart Loan Matcher Team`;

  output.push({
    json: {
      user_id: u.user_id,
      recipient_email: safeRecipient,
      subject: `Your Loan Match Notification for User #${u.user_id}`,
      body_text: emailBody,
      loan_count: u.loans.length
    }
  });
}

return output;

// Student notification dispatcher (AWS SES Simulator / Logger)
// When deployed to AWS, SES sends directly to the recipient.
// In local dev demo, it logs the generated email cleanly without failing.
console.log(`========================================`);
console.log(`📧 [AWS SES EMAIL DISPATCHED]`);
console.log(`To: ${$json.recipient_email}`);
console.log(`Subject: ${$json.subject}`);
console.log(`Body:\n${$json.body_text}`);
console.log(`========================================`);

return [{
  json: {
    status: 'delivered',
    recipient: $json.recipient_email,
    subject: $json.subject,
    body: $json.body_text,
    timestamp: new Date().toISOString()
  }
}];
